questionvariables.text:
/* Perfect-square products give whole PA and PT (PT = sqrt(PA*PB)). */
data : sublist(
  create_list([pa,ab], pa,2,14, ab,2,26),
  lambda([z], is(
        integerp(sqrt(z[1]*(z[1]+z[2])))
    and sqrt(z[1]*(z[1]+z[2])) >= 4 and sqrt(z[1]*(z[1]+z[2])) <= 18
    and z[1]+z[2] <= 32 )));
sel : rand(data);
PA : sel[1];
AB : sel[2];
PB : PA + AB;
ta_pt : sqrt(PA*PB);          /* tangent length */
ta_pa : PA;                   /* answer to (b) */
/* geometry for marking the placed point A (same layout as the JSXGraph block) */
ua : float(cos(150*%pi/180));
va : float(sin(150*%pi/180));
ta_Ax : float(PA*ua);
ta_Ay : float(PA*va);
ta_A : [ta_Ax, ta_Ay];
Bx : float(PB*ua);
By : float(PB*va);
B_pt : [Bx, By];
/* distractors for (b) */
wrong_useAB_b : PA*PB/AB;     /* used PT^2 = PA*AB -> PA = PT^2/AB */
